/* Post grid — nine posts a page, with ← Older Entries / Next Entries → under the
   cards.

   The renderer this site runs has no paged posts source and no pager block (both
   only exist on an unmerged platform branch), so the paging lives here. The
   topic chips are the platform's `filter` behaviour and are untouched: it hides
   the cards a chip rules out and fires `bz:filter`, and this script then shows
   one page of whatever is left. Choosing a chip goes back to page 1.

   Without this script — the Design canvas, or a visitor with scripts off — every
   card is in the grid and there is no pager, so nothing is ever unreachable.
   The page number rides in the address (?page=2), so a page can be linked to and
   the browser's back button steps back through pages. */
(function () {
  var PER_PAGE = 9;

  function init(band) {
    var root = band.querySelector('[data-bz-behavior="filter"]') || band;
    var cards = band.querySelector('[data-bz-node="pr-cards"]');
    if (!cards) return;
    var items = Array.prototype.slice.call(cards.querySelectorAll('[data-bz-part="item"]'));
    if (!items.length) return;
    var head = band.querySelector('[data-bz-node="pr-head-row"]') || cards;

    var nav = document.createElement('nav');
    nav.className = 'ss-pager';
    nav.setAttribute('aria-label', 'Blog pages');
    nav.hidden = true;
    // The whole list's size, as the platform pager carried it: the blog page's
    // own script reads it so "All" counts every post rather than this page's nine.
    nav.setAttribute('data-bz-posts-total', String(items.length));
    cards.appendChild(nav);

    function pageFromUrl() {
      var n = parseInt(new URLSearchParams(window.location.search).get('page'), 10);
      return n > 0 ? n : 1;
    }
    function urlFor(n) {
      var url = new URL(window.location.href);
      if (n > 1) url.searchParams.set('page', String(n));
      else url.searchParams.delete('page');
      url.hash = '';
      return url.pathname + url.search;
    }

    var page = pageFromUrl();

    // The filter behaviour marks every card data-bz-match="1|0" and has already
    // run by the time this script does (platform scripts load first).
    function matched() {
      return items.filter(function (item) { return item.getAttribute('data-bz-match') !== '0'; });
    }

    function link(label, target, cls, rel) {
      var el;
      if (target) {
        el = document.createElement('a');
        el.href = urlFor(target);
        el.rel = rel;
        el.setAttribute('data-page', String(target));
      } else {
        el = document.createElement('span');
        el.setAttribute('aria-disabled', 'true');
      }
      el.className = 'ss-pager__link ' + cls;
      el.textContent = label;
      return el;
    }

    function render() {
      var shown = matched();
      var total = Math.max(1, Math.ceil(shown.length / PER_PAGE));
      if (page > total) page = total;
      var start = (page - 1) * PER_PAGE;
      shown.forEach(function (item, i) { item.hidden = i < start || i >= start + PER_PAGE; });

      nav.textContent = '';
      nav.hidden = total < 2;
      if (total < 2) return;
      var status = document.createElement('span');
      status.className = 'ss-pager__status';
      status.textContent = 'Page ' + page + ' of ' + total;
      // Older posts are further on, as on the rest of the blog: ← Older Entries
      // sits left and Next Entries → right, whichever of them is live.
      nav.appendChild(link('← Older Entries', page < total ? page + 1 : null, 'ss-pager__older', 'next'));
      nav.appendChild(status);
      nav.appendChild(link('Next Entries →', page > 1 ? page - 1 : null, 'ss-pager__newer', 'prev'));
    }

    function go(n, push) {
      page = n;
      render();
      if (push) window.history.pushState({ ssPage: n }, '', urlFor(n));
      var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      head.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'start' });
    }

    nav.addEventListener('click', function (event) {
      var a = event.target.closest && event.target.closest('a[data-page]');
      if (!a || event.metaKey || event.ctrlKey || event.shiftKey || event.button) return;
      event.preventDefault();
      go(parseInt(a.getAttribute('data-page'), 10), true);
    });

    // A chip changes the set, so the reader starts again at its first page.
    root.addEventListener('bz:filter', function () {
      if (page !== 1) {
        page = 1;
        window.history.replaceState(null, '', urlFor(1));
      }
      render();
    });

    window.addEventListener('popstate', function () {
      var n = pageFromUrl();
      if (n !== page) go(n, false);
    });

    render();
  }

  document.querySelectorAll('[data-bz-section="post-rail"]').forEach(init);
})();
